#!/bin/bash
set -euo pipefail
f=/home/ubuntu/ns-lab/evidence/08-user.json; pf=/home/ubuntu/ns-lab/state/08-user.pid
/usr/bin/setpriv --reuid=ubuntu --regid=ubuntu --init-groups /usr/bin/unshare --user --map-root-user /bin/bash -c '/usr/bin/jq -n --argjson pid "$$" --argjson uid "$(/usr/bin/id -u)" --argjson gid "$(/usr/bin/id -g)" --arg uid_map "$(/bin/cat /proc/self/uid_map)" --arg gid_map "$(/bin/cat /proc/self/gid_map)" "{pid:\$pid,inside_uid:\$uid,inside_gid:\$gid,host_uid:1000,uid_map:\$uid_map,gid_map:\$gid_map}" > /home/ubuntu/ns-lab/evidence/08-user.json; exec /usr/local/lib/ns-lab/ns-demo /home/ubuntu/ns-lab/evidence/08-user-inner.json user' & p=$!
/usr/bin/printf '%s\n' "$p" > "$pf"; /usr/bin/sleep 1; host_uid=$(/usr/bin/awk '/^Uid:/{print $2}' "/proc/$p/status"); /usr/bin/jq --argjson p "$p" --argjson uid "$host_uid" '.pid=$p|.host_uid=$uid' "$f" > /home/ubuntu/ns-lab/state/ns-lab-user.json; /bin/mv /home/ubuntu/ns-lab/state/ns-lab-user.json "$f"; /usr/bin/chown ubuntu:ubuntu "$f" "$pf"
